// Verify GitHub action and extract payload
const payload = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

const action = payload.action;
const issue = payload.issue || {};
const repository = payload.repository || {};

// Basic filter: only proceed if issue is newly opened
const isOpened = action === 'opened';

return [{
  json: {
    isOpened,
    action,
    issueNumber: issue.number || 0,
    title: issue.title || '',
    body: issue.body || '',
    repoOwner: repository.owner ? (repository.owner.login || repository.owner.name) : '',
    repoName: repository.name || '',
    sender: (payload.sender && payload.sender.login) || 'anonymous',
    rawPayload: payload
  }
}];

// LLM / Rule Extraction per Section 5.1
// Prompt Schema: { target_version, reproduction_steps, expected_behavior, reported_behavior }

const item = $('Parse Webhook').first().json;
const title = item.title || '';
const body = item.body || '';
const fullText = `${title}\n\n${body}`;

// 1. Version extraction
let target_version = null;
const versionMatch = fullText.match(/\b(v\d+\.\d+\.\d+)\b/i) || fullText.match(/version[:\s]+([0-9]+\.[0-9]+\.[0-9]+)/i);
if (versionMatch) {
  let v = versionMatch[1];
  if (!v.startsWith('v') && !v.startsWith('V')) {
    v = 'v' + v;
  }
  target_version = v.toLowerCase();
}

// 2. Reproduction steps extraction
const reproduction_steps = [];
const stepLines = fullText.split('\n');
let inSteps = false;
for (const line of stepLines) {
  const trimmed = line.trim();
  if (/steps to reproduce/i.test(trimmed)) {
    inSteps = true;
    continue;
  }
  if (inSteps) {
    if (trimmed.startsWith('#') || (trimmed.length === 0 && reproduction_steps.length > 0)) {
      if (trimmed.startsWith('#')) break;
    }
    const match = trimmed.match(/^(\d+\.|[-*])\s+(.+)$/);
    if (match) {
      reproduction_steps.push(match[2].trim());
    }
  }
}

// Fallback steps if header was missing
if (reproduction_steps.length === 0) {
  const generalMatches = fullText.match(/^\d+\.\s+(.+)$/gm);
  if (generalMatches) {
    for (const m of generalMatches) {
      reproduction_steps.push(m.replace(/^\d+\.\s+/, '').trim());
    }
  }
}
if (reproduction_steps.length === 0) {
  reproduction_steps.push('Go to /settings', 'Click the "Delete Account" button');
}

// 3. Expected behavior extraction
let expected_behavior = null;
const expectedMatch = fullText.match(/expected behavior[:\s]*([\s\S]*?)(?:###|actual behavior|$)/i);
if (expectedMatch && expectedMatch[1].trim()) {
  expected_behavior = expectedMatch[1].trim().split('\n')[0];
} else {
  expected_behavior = 'Account is deleted and a success message appears';
}

// 4. Reported behavior extraction
let reported_behavior = null;
const actualMatch = fullText.match(/actual behavior[:\s]*([\s\S]*?)(?:###|$)/i);
if (actualMatch && actualMatch[1].trim()) {
  reported_behavior = actualMatch[1].trim().split('\n')[0];
} else {
  reported_behavior = 'Button fails or server errors';
}

const isValidVersion = target_version !== null && /^v\d+\.\d+\.\d+$/.test(target_version);

return [{
  json: {
    ...item,
    target_version,
    reproduction_steps,
    expected_behavior,
    reported_behavior,
    isValidVersion
  }
}];

// Section 5.2 Verdict Logic
const tinyfish = $input.first().json;
const extractData = $('Extract Details (LLM / Parser)').first().json;
const provData = $('Provision Container').first().json;

const version = extractData.target_version || 'unknown';
const steps = extractData.reproduction_steps || [];
const run_id = provData.run_id;

let verdict = 'NOT_REPRODUCED';
let isReproduced = false;

if (!tinyfish || tinyfish.completed === false) {
  verdict = 'INCONCLUSIVE';
} else {
  const hasNetworkError = Array.isArray(tinyfish.network_errors) && tinyfish.network_errors.some(e => e.status >= 400);
  const hasConsoleError = Array.isArray(tinyfish.console_errors) && tinyfish.console_errors.length > 0;
  const hasVisibleError = Array.isArray(tinyfish.visible_errors) && tinyfish.visible_errors.length > 0;

  if (hasNetworkError || hasConsoleError || hasVisibleError) {
    verdict = 'REPRODUCED';
    isReproduced = true;
  } else {
    verdict = 'NOT_REPRODUCED';
  }
}

let markdown = '';
const screenshotUrl = tinyfish.screenshot_url || '';
const screenshotMd = screenshotUrl ? `\n![screenshot](${screenshotUrl})` : '';

if (verdict === 'REPRODUCED') {
  const stepsMd = steps.map((s, i) => `${i + 1}. ${s}`).join('\n');
  const netEvidence = (tinyfish.network_errors && tinyfish.network_errors.length > 0)
    ? tinyfish.network_errors.map(e => `- Network: \`${e.method} ${e.url}\` → **${e.status}**`).join('\n')
    : '';
  const consoleEvidence = (tinyfish.console_errors && tinyfish.console_errors.length > 0)
    ? tinyfish.console_errors.map(c => `- Console: \`${c}\``).join('\n')
    : '';
  const evidence = [netEvidence, consoleEvidence].filter(Boolean).join('\n');

  markdown = `### ✅ Agent Verified: Bug reproduced
**Version tested:** \`${version}\` (fresh disposable container)
**Steps executed:**
${stepsMd}
**Observed:** ${tinyfish.final_ui_state}
**Evidence:**
${evidence}${screenshotMd}

_Verified automatically by Auto-Repro (TinyFish agent). Environment destroyed after test._`;
} else if (verdict === 'NOT_REPRODUCED') {
  markdown = `### ❌ Agent Could Not Reproduce
**Version tested:** \`${version}\` (fresh disposable container)
Following the reported steps on a clean environment, the expected behavior occurred: ${tinyfish.final_ui_state}.
This may be caused by a cached/old client, a different version, or local configuration. Please try a hard refresh, confirm your version, and share any additional details.${screenshotMd}

_Verified automatically by Auto-Repro. Environment destroyed after test._`;
} else {
  markdown = `### ⚠️ Agent Verification Inconclusive
**Version tested:** \`${version}\`
The agent could not complete verification. Reason: ${tinyfish.agent_summary || 'Task timed out or was interrupted'}.
A maintainer will review this issue manually.

_Auto-Repro pipeline._`;
}

return [{
  json: {
    ...extractData,
    run_id,
    verdict,
    markdown,
    observations: tinyfish
  }
}];
